CREATE TABLE users (id BIGSERIAL PRIMARY KEY, email VARCHAR(254) UNIQUE NOT NULL, password_hash TEXT NOT NULL, first_name VARCHAR(80), last_name VARCHAR(80), role VARCHAR(20) NOT NULL DEFAULT 'customer', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE addresses (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, label VARCHAR(40), line1 TEXT NOT NULL, line2 TEXT, city VARCHAR(100) NOT NULL, region VARCHAR(100), postal_code VARCHAR(24) NOT NULL, country_code CHAR(2) NOT NULL, is_default BOOLEAN NOT NULL DEFAULT false);
CREATE TABLE categories (id BIGSERIAL PRIMARY KEY, parent_id BIGINT REFERENCES categories(id) ON DELETE SET NULL, name VARCHAR(100) NOT NULL, slug VARCHAR(120) UNIQUE NOT NULL);
CREATE TABLE products (id BIGSERIAL PRIMARY KEY, category_id BIGINT REFERENCES categories(id) ON DELETE SET NULL, name VARCHAR(180) NOT NULL, slug VARCHAR(200) UNIQUE NOT NULL, description TEXT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'draft', featured BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE product_variants (id BIGSERIAL PRIMARY KEY, product_id BIGINT NOT NULL REFERENCES products(id) ON DELETE CASCADE, sku VARCHAR(80) UNIQUE NOT NULL, title VARCHAR(120) NOT NULL, price_cents INTEGER NOT NULL CHECK(price_cents>=0), compare_at_cents INTEGER, stock_quantity INTEGER NOT NULL DEFAULT 0 CHECK(stock_quantity>=0), attributes JSONB NOT NULL DEFAULT '{}');
CREATE TABLE product_images (id BIGSERIAL PRIMARY KEY, product_id BIGINT NOT NULL REFERENCES products(id) ON DELETE CASCADE, url TEXT NOT NULL, alt_text VARCHAR(240) NOT NULL, position SMALLINT NOT NULL DEFAULT 0);
CREATE TABLE carts (id UUID PRIMARY KEY, user_id BIGINT REFERENCES users(id) ON DELETE CASCADE, session_id VARCHAR(120), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE cart_items (cart_id UUID NOT NULL REFERENCES carts(id) ON DELETE CASCADE, variant_id BIGINT NOT NULL REFERENCES product_variants(id) ON DELETE CASCADE, quantity INTEGER NOT NULL CHECK(quantity>0), PRIMARY KEY(cart_id,variant_id));
CREATE TABLE orders (id UUID PRIMARY KEY, user_id BIGINT REFERENCES users(id) ON DELETE SET NULL, email VARCHAR(254) NOT NULL, status VARCHAR(30) NOT NULL, currency CHAR(3) NOT NULL DEFAULT 'USD', subtotal_cents INTEGER NOT NULL, shipping_cents INTEGER NOT NULL DEFAULT 0, tax_cents INTEGER NOT NULL DEFAULT 0, total_cents INTEGER NOT NULL, shipping_address JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE order_items (id BIGSERIAL PRIMARY KEY, order_id UUID NOT NULL REFERENCES orders(id) ON DELETE CASCADE, variant_id BIGINT REFERENCES product_variants(id) ON DELETE SET NULL, product_name VARCHAR(180) NOT NULL, sku VARCHAR(80) NOT NULL, unit_price_cents INTEGER NOT NULL, quantity INTEGER NOT NULL CHECK(quantity>0));
CREATE TABLE payments (id BIGSERIAL PRIMARY KEY, order_id UUID NOT NULL REFERENCES orders(id) ON DELETE CASCADE, provider VARCHAR(40) NOT NULL, provider_reference VARCHAR(180), amount_cents INTEGER NOT NULL, status VARCHAR(30) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE reviews (id BIGSERIAL PRIMARY KEY, product_id BIGINT NOT NULL REFERENCES products(id) ON DELETE CASCADE, user_id BIGINT REFERENCES users(id) ON DELETE SET NULL, rating SMALLINT NOT NULL CHECK(rating BETWEEN 1 AND 5), body TEXT, status VARCHAR(20) NOT NULL DEFAULT 'pending', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE wishlists (user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, product_id BIGINT NOT NULL REFERENCES products(id) ON DELETE CASCADE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(user_id,product_id));
CREATE INDEX idx_products_category_status ON products(category_id,status); CREATE INDEX idx_orders_user_created ON orders(user_id,created_at DESC); CREATE INDEX idx_reviews_product_status ON reviews(product_id,status);
